package android.os; public class Handler {final Looper l; public Handler(Looper looper){l=looper;} public Looper getLooper(){return l;} public boolean post(Runnable r){return postDelayed(r,0);} public boolean postDelayed(Runnable r,long d){if(l.closed)return false;Looper.jobs.add(new Looper.Job(l,r,Looper.now+d));return true;} public void removeCallbacks(Runnable r){Looper.jobs.removeIf(j->j.owner==l && j.run==r);} }